<script lang="ts">import { ShoppingBag, Minus, Plus, Trash2, ArrowLeft, Heart } from 'lucide-svelte'; import { cart, cartCount, setQuantity, toggleWishlist, wishlist, notify } from '../lib/stores/commerce'; import { products, money } from '../lib/data/products'; import OrderSummary from '../lib/components/OrderSummary.svelte';</script>
<div class="page-heading compact"><div class="breadcrumbs"><a href="#/">Home</a><span>/</span><span>Your bag</span></div><h1>Your bag<span class="heading-count">({$cartCount})</span></h1><p>A few beautiful choices. All in one place.</p></div>
{#if $cart.length}<section class="bag-layout"><div><div class="free-shipping-note">A little welcome awaits. Use <strong>WELCOME15</strong> for 15% off your demo bag.</div><div class="cart-items">{#each $cart as item (`${item.productId}-${item.size}-${item.color}`)}{@const product=products.find(p=>p.id===item.productId)!}<article class="cart-item"><a href={`#/product/${product.id}`}><img src={product.image} alt={product.name}/></a><div class="cart-item-info"><span class="eyebrow">{product.category}</span><h3><a href={`#/product/${product.id}`}>{product.name}</a></h3><p>{item.color} / Size {item.size}</p><div class="cart-item-bottom"><div class="quantity-control"><button aria-label={`Decrease ${product.name} quantity`} onclick={()=>setQuantity(item,item.quantity-1)}><Minus size={13}/></button><span>{item.quantity}</span><button aria-label={`Increase ${product.name} quantity`} disabled={item.quantity>=10} onclick={()=>setQuantity(item,item.quantity+1)}><Plus size={13}/></button></div><button class="inline-button" aria-label={`Remove ${product.name}`} onclick={()=>setQuantity(item,0)}><Trash2 size={14}/>Remove</button><button class="inline-button save-cart" onclick={()=>{if(!$wishlist.includes(product.id))toggleWishlist(product.id);setQuantity(item,0);notify('Moved to your wishlist');}}><Heart size={14}/>Save for later</button></div></div><div class="cart-line-price"><strong>{money(product.price*item.quantity)}</strong>{#if product.originalPrice}<s>{money(product.originalPrice*item.quantity)}</s>{/if}</div></article>{/each}</div><a class="text-link" href="#/shop"><ArrowLeft size={15}/>Continue exploring</a></div><OrderSummary/></section>{:else}<section class="empty-state"><ShoppingBag size={42}/><h2>Your next story starts here.</h2><p>Your bag is waiting for something beautiful.</p><a class="button dark" href="#/shop">Explore the collection ↗</a></section>{/if}
